import{_ as p,o as e,c as s,a3 as r}from"./chunks/framework.BWzgKoSO.js";const o="/incomplete-weight-loss-guide/images/exercise/ex-squat.jpg",i="/incomplete-weight-loss-guide/images/exercise/ex-pushup-incline.jpg",g="/incomplete-weight-loss-guide/images/exercise/ex-pushup.jpg",a="/incomplete-weight-loss-guide/images/exercise/ex-glute-bridge.jpg",d="/incomplete-weight-loss-guide/images/exercise/ex-lunge.jpg",n="/incomplete-weight-loss-guide/images/exercise/ex-plank.jpg",l="/incomplete-weight-loss-guide/images/exercise/ex-calf-raise.jpg",c="/incomplete-weight-loss-guide/images/exercise/ex-goblet-squat.jpg",h="/incomplete-weight-loss-guide/images/exercise/ex-one-arm-row.jpg",m="/incomplete-weight-loss-guide/images/exercise/ex-db-bench.jpg",_="/incomplete-weight-loss-guide/images/exercise/ex-rdl.jpg",u="/incomplete-weight-loss-guide/images/exercise/ex-db-shoulder-press.jpg",x="/incomplete-weight-loss-guide/images/exercise/ex-farmers-walk.jpg",b="/incomplete-weight-loss-guide/images/exercise/ex-leg-press.jpg",q="/incomplete-weight-loss-guide/images/exercise/ex-lat-pulldown.jpg",w="/incomplete-weight-loss-guide/images/exercise/ex-cable-row.jpg",j="/incomplete-weight-loss-guide/images/exercise/ex-machine-chest-press.jpg",f="/incomplete-weight-loss-guide/images/exercise/ex-leg-curl.jpg",P="/incomplete-weight-loss-guide/images/exercise/ex-crunch.jpg",k="/incomplete-weight-loss-guide/images/exercise/ex-run-trail.jpg",B="/incomplete-weight-loss-guide/images/exercise/ex-dead-bug.jpg",A="/incomplete-weight-loss-guide/images/exercise/ex-side-plank.jpg",C="/incomplete-weight-loss-guide/images/exercise/ex-superman.jpg",I="/incomplete-weight-loss-guide/images/exercise/ex-step-up.jpg",T="/incomplete-weight-loss-guide/images/exercise/ex-single-glute-bridge.jpg",R="/incomplete-weight-loss-guide/images/exercise/ex-mountain-climber.jpg",G="/incomplete-weight-loss-guide/images/exercise/ex-walk-incline.jpg",M="/incomplete-weight-loss-guide/images/exercise/ex-runner-stretch.jpg",N="/incomplete-weight-loss-guide/images/exercise/ex-hip-flexor-stretch.jpg",E="/incomplete-weight-loss-guide/images/value/ranking-hang-to-la.jpg",J=JSON.parse('{"title":"第四部分　怎么练","description":"","frontmatter":{},"headers":[],"relativePath":"ch04-training.md","filePath":"ch04-training.md","lastUpdated":1793419815000}'),S={name:"ch04-training.md"};function D($,t,v,V,y,F){return e(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="第四部分-怎么练" tabindex="-1">第四部分　怎么练 <a class="header-anchor" href="#第四部分-怎么练" aria-label="Permalink to &quot;第四部分　怎么练&quot;">​</a></h1><p>这一部分比前面短，因为练这件事，能做的其实不多，做对了就够。</p><h2 id="_4-1-什么算大基数" tabindex="-1">4.1　什么算大基数 <a class="header-anchor" href="#_4-1-什么算大基数" aria-label="Permalink to &quot;4.1　什么算大基数&quot;">​</a></h2><p>先把标准摆出来，别凭感觉。</p><p>按中国的成人体重判定标准：BMI 24 到 27.9 算超重，28 及以上算肥胖〔G8，A〕。腰围男性 ≥90 厘米、女性 ≥85 厘米，算中心型肥胖。</p><p>举个数：1.75 米的人，超重线是 73.5 公斤，肥胖线是 85.75 公斤。</p><p>腰围怎么量：站直，放松，别收腹，皮尺绕肚脐那一圈，呼气末读。同一个位置、同一个时间量，才有比较的意义。</p><p>但“大基数”这个词，我想给它换个说法。它真正问的不是你多重，是你的<strong>关节和心肺现在扛不扛得住跑跳</strong>。</p><p>所以判断用两个数：BMI 和腰围。BMI ≥28，或者比标准体重多出 20 公斤以上，就按大基数对待——先走，先下水，别急着跑。</p><h2 id="_4-2-大基数-先吃后练" tabindex="-1">4.2　大基数：先吃后练 <a class="header-anchor" href="#_4-2-大基数-先吃后练" aria-label="Permalink to &quot;4.2　大基数：先吃后练&quot;">​</a></h2><p>我自己的顺序：先游泳，掉了 10 斤左右，然后才转跑步。</p><p>为什么不一上来就跑？膝盖。</p><p>膝的问题从来不是一个原因，是三件叠加：体重压在上面，大腿和臀部的肌肉撑不住，跑量涨得比身体适应得快。三件里改一件，风险就下来一截；三件一起做，第二个月就得去挂号。</p><p><strong>起步分三档，对号入座。</strong></p><p><strong>第一档</strong>，BMI ≥30，或者很久没动过：走。每天 20 到 30 分钟，分成两段也行。有条件就下水游泳，水里膝关节的负担比陆地上小得多。每周 3 到 5 次。</p><p><strong>第二档</strong>，BMI 24 到 30，走了一个月不难受：走路照旧，加自重抗阻，每周 2 次，每次 15 分钟（动作见 4.4 的第二套）。有氧可以拉长到 40 分钟。</p><p><strong>第三档</strong>，能轻松走一小时了：开始跑，但用走跑交替——跑 1 分钟，走 2 分钟，重复 8 次。不追配速，追总时间。每周加量不超过上周的 10%。</p><p>这一档一档往上走的道理，跟指南说的“循序渐进”是一回事〔G1，A〕。</p><p><strong>再说一天的活动量。</strong></p><p>指南给的量是：中低强度有氧为主、抗阻为辅，有氧每周 150 到 300 分钟，每周 5 到 7 天，至少隔天一次；抗阻每周 2 到 3 天，每次 10 到 20 分钟；每周通过运动消耗 2000 千卡以上〔G1，A〕。</p><p>这个量不小。别把它当门槛，当方向。你现在一周只走三次，先走到五次，就是进步。</p><p>还有一条容易忽略的：每天静坐和被动看屏幕的时间控制在 2 到 4 小时以内，长期伏案的人每小时起来活动 3 到 5 分钟〔G1，A〕。这一条不花你任何意志力，收益比一次硬撑的训练大。</p><p><strong>第一周可以这么排</strong>（按第一档写，第二三档往上加）：</p><ul><li>周一：走 30 分钟</li><li>周二：休</li><li>周三：走 30 分钟 + 15 分钟自重（4.4 的 A 套）</li><li>周四：休</li><li>周五：走 30 分钟</li><li>周六：游泳或快走 40 分钟</li><li>周日：休，但别躺一天，出门走两趟</li></ul><p>一周动五次，加起来两个多小时，就到指南给的量了。</p><h2 id="_4-3-纯做有氧掉肌肉" tabindex="-1">4.3　纯做有氧掉肌肉 <a class="header-anchor" href="#_4-3-纯做有氧掉肌肉" aria-label="Permalink to &quot;4.3　纯做有氧掉肌肉&quot;">​</a></h2><p>这话对，但要加条件。</p><p>掉肌肉不是有氧的错，是四件事凑齐了才会明显：赤字开得太大、蛋白质吃不够、完全没有抗阻刺激、睡不够。</p><p>四件里你有三件，跑得再多也留不住肌肉。</p><p>指南在这件事上说得很清楚：减重过程中不能只看体重，要看体脂率和肌肉量的变化，目标是减少肌肉流失、维持肌肉量和基础代谢率〔G1，A〕。它给的手段就是抗阻运动每周 2 到 3 天。</p><p>我说句自己的：我 78 天里，抗阻一次都没系统练过。所以我掉的那 26.15 公斤里有多少是肌肉，我没有数据。这不是谦虚，这是我这本书的缺口，第四部分就是为了补它才写的。</p><h2 id="_4-4-抗阻最小方案" tabindex="-1">4.4　抗阻最小方案 <a class="header-anchor" href="#_4-4-抗阻最小方案" aria-label="Permalink to &quot;4.4　抗阻最小方案&quot;">​</a></h2><p>三套，每套 6 个动作，每周 2 到 3 次，隔天做。都不需要请教练。</p><p><strong>A 套：自重，家里一块垫子就够</strong></p><p>深蹲、俯卧撑（推墙起步，进阶到跪姿）、臀桥、弓步、平板支撑、提踵。</p><p>每个动作 2 组，8 到 12 次；平板支撑 20 到 40 秒。</p><p>下面每个动作配一张分解图，左格是起始，右格是做到位。照片来自 Free Exercise DB（公有领域），我按起止两帧拼在一起，标上了要点。</p><p>这几个动作，先把姿势做对，再谈组数。姿势错了，练的是伤。</p><p><strong>深蹲</strong></p><p><img src="'+o+'" alt="深蹲分解图：左图站直双脚与肩同宽，右图下蹲到大腿接近水平"></p><p>膝盖跟着脚尖方向，别往里扣；重心在脚掌中后段。起步就用椅子：站起来、坐下，不许用手撑。</p><p><strong>俯卧撑（两个版本）</strong></p><p><img src="'+i+'" alt="上斜俯卧撑分解图"></p><p><img src="'+g+'" alt="标准俯卧撑分解图"></p><p>身体成一条线，臀别塌。推墙或手撑桌子是上斜版，撑得越高越省力；能做到十个标准俯卧撑再往上加难度。</p><p><strong>臀桥</strong></p><p><img src="'+a+'" alt="臀桥分解图"></p><p>用屁股发力，不是用腰挺起来。顶到髋、肩、膝一条线就停，别往上翻腰。</p><p><strong>弓步</strong></p><p><img src="'+d+'" alt="弓步分解图"></p><p>前膝不超过脚尖太多，后膝垂直往地面去。站不稳就扶墙，别硬撑。</p><p><strong>平板支撑</strong></p><p><img src="'+n+'" alt="平板支撑分解图"></p><p>腰别塌，宁可缩短时间，也别撑着塌腰。撑不住就跪姿，跪着撑一分钟比塌腰撑三十秒强。</p><p><strong>提踵</strong></p><p><img src="'+l+'" alt="提踵分解图"></p><p>慢慢落，落下去那两秒才是关键。踮到最高停一下再放。</p><p><strong>B 套：一对哑铃（各 10 到 15 公斤，或一个壶铃）</strong></p><p>高脚杯深蹲、单臂划船、哑铃卧推、罗马尼亚硬拉、肩上推、负重走。每个 3 组，8 到 12 次。</p><p><strong>高脚杯深蹲</strong></p><p><img src="'+c+'" alt="高脚杯深蹲分解图"></p><p>重物抱在胸前，蹲的时候胸别往前扑，膝跟着脚尖方向。</p><p><strong>单臂划船</strong></p><p><img src="'+h+'" alt="单臂划船分解图"></p><p>一手撑椅子，背保持平直；肘往后拉到腰侧，别耸肩、别甩身体。这个动作伤了肩，要养很久。</p><p><strong>哑铃卧推</strong></p><p><img src="'+m+'" alt="哑铃卧推分解图"></p><p>下到胸两侧，推到手臂伸直但不锁死。没有凳子的，躺在地板上做，肘碰到地面就起。</p><p><strong>罗马尼亚硬拉</strong></p><p><img src="'+_+'" alt="罗马尼亚硬拉分解图"></p><p>靠屈髋把重物沿大腿往下放，背始终平直，感觉大腿后侧拉开就起身。别追着让重物触地——硬拉弓背是腰伤最常见的一幕。</p><p><strong>肩上推</strong></p><p><img src="'+u+'" alt="肩上推分解图"></p><p>从肩高往上推，别用腰后仰借力。坐着做能逼掉一部分借力。</p><p><strong>负重走</strong></p><p><img src="'+x+'" alt="负重走分解图"></p><p>两手各提一个重物，站直往前走，肩不歪、腰不塌。走 30 到 60 秒算一组，这个动作练的是核心和握力，比看上去累。</p><p><strong>C 套：健身房器械</strong></p><p>腿举、高位下拉、坐姿划船、胸推、腿弯举、卷腹。每个 3 组，10 到 12 次。</p><p>器械的好处是轨迹固定，不容易做错；坏处是重量加得太快，人容易只推得动前半程。</p><p><strong>腿举</strong></p><p><img src="'+b+'" alt="腿举分解图"></p><p>脚踩踏板与肩同宽，下到大腿接近胸口，蹬起时膝盖别锁死。</p><p><strong>高位下拉</strong></p><p><img src="'+q+'" alt="高位下拉分解图"></p><p>宽握，先让肩胛往下沉，再拉到上胸。别靠身体后仰去拽。</p><p><strong>坐姿划船</strong></p><p><img src="'+w+'" alt="坐姿划船分解图"></p><p>坐稳，先收肩胛再拉，拉到腹部，别用腰往后仰。</p><p><strong>胸推（器械）</strong></p><p><img src="'+j+'" alt="器械胸推分解图"></p><p>握把在胸两侧，推到手臂伸直，肩别耸。</p><p><strong>腿弯举</strong></p><p><img src="'+f+'" alt="腿弯举分解图"></p><p>慢慢屈膝把滚垫拉过来，放回去的那两三秒才是重点。</p><p><strong>卷腹</strong></p><p><img src="'+P+'" alt="卷腹分解图"></p><p>只起肩背，腰不离地。别用手拉脖子——脖子疼的人九成是这么来的。</p><p><strong>30 分钟版</strong>：热身 5 分钟，六个动作按顺序做 3 轮（每轮之间歇 60 到 90 秒），最后拉伸 5 分钟。</p><p><strong>15 分钟版</strong>：只做三个动作——一个蹲（腿）、一个推（胸肩）、一个拉（背），每个 3 组。时间不够的时候，做这三个比不做强太多。</p><p><strong>三条原则：</strong></p><p>重量选到最后一两次有点吃力、但动作不变形。变形的重量不算数。</p><p>组间歇够，别赶。你要的是刺激，不是心率。</p><p>关节疼就停，肌肉酸可以继续。这条分不清的人最容易受伤。</p><h2 id="_4-5-小基数" tabindex="-1">4.5　小基数 <a class="header-anchor" href="#_4-5-小基数" aria-label="Permalink to &quot;4.5　小基数&quot;">​</a></h2><p>BMI 24 以下、腰围正常的人，重点该从“减重”换成“改体型”。</p><p>做法：抗阻每周 3 次，有氧 2 次，缺口开小一点，300 到 500 千卡。</p><p>这个阶段最常见的情况是体重不动，裤腰在动。别急着看秤，看照片和腰围。</p><h2 id="_4-6-有氧怎么选-还有那些零碎的动" tabindex="-1">4.6　有氧怎么选，还有那些零碎的动 <a class="header-anchor" href="#_4-6-有氧怎么选-还有那些零碎的动" aria-label="Permalink to &quot;4.6　有氧怎么选，还有那些零碎的动&quot;">​</a></h2><p><strong>关节负担从低到高排</strong>：游泳、椭圆机 → 骑车 → 快走 → 慢跑 → 跳绳和高强度间歇。</p><p>按你现在的体重选，不是按别人的推荐选。80 公斤的人和 55 公斤的人，能承受的不是一回事。</p><p><strong>每天 6000 步</strong>是膳食指南给普通成年人的基本量〔G2，A〕。减重期往上加到 8000 到 12000 更好。走路这件事的好处是它不占时间——通勤、打电话、饭后十分钟，都能算进去。</p><p><strong>爬楼有个诀窍</strong>：上去爬，下来坐电梯。上楼的负荷是往上推，下楼是刹车，膝盖最怕的是刹车〔C〕。</p><p><strong>别小看零碎的动</strong>：站着打电话、饭后走十分钟、地铁早下一站。一天多走三千步，不占你一分钟额外时间，也不吃你的意志力。</p><p>练这件事，最值钱的不是强度，是不停。</p><h2 id="_4-7-跑步到底怎么跑" tabindex="-1">4.7　跑步到底怎么跑 <a class="header-anchor" href="#_4-7-跑步到底怎么跑" aria-label="Permalink to &quot;4.7　跑步到底怎么跑&quot;">​</a></h2><p>跑步的技术，吵了几十年。能落到地上的其实就三条：步频别太低，落脚别伸到身体前面，量别加太快。剩下的那些——前脚掌还是后脚跟、胳膊摆多少度、要不要上碳板鞋——要么证据不硬，要么跟减重没关系。</p><p><strong>先说步频。</strong></p><p>步频是一分钟落多少步。新手跑起来常常 150 到 160，专业选手常在 180 上下，于是“180”这个数就被传成了标准。它不是标准。</p><p>有研究让跑者把步频提高 5% 到 10%，髋、膝的关节负荷和下肢冲击都降下来了，步幅也跟着缩短〔R15，B〕。注意被支持的那句话是“比你现在的步频快一点”，不是“必须跑到 180”。</p><p>怎么用：数你现在三十秒落多少步，乘二，再往上加一成。150 的加到 165 左右就够，别一步跳到 180，改了步频又改姿势，身体同时适应两件事，最容易伤。</p><p><strong>再说落脚。</strong></p><p>跑步圈吵得最凶的是前脚掌还是后脚跟落地。有一项系统综述把五十三项研究收在一起看：改成前脚掌落地，膝盖的屈曲幅度和髌股关节的应力确实低了，但负荷挪到了踝关节和小腿的跖屈肌上；跑步经济性没有改善的证据；至于受伤风险，现有研究几乎都是回顾性的，缺前瞻性证据，关系定不下来。作者的结论很干脆：对一个没受伤的、习惯后脚跟落地的人，不建议改〔R16，B〕。</p><p>所以不用刻意改，也别信“改了姿势就能跑更快”这种话。但有一件事值得改——落脚点别伸得太靠前。</p><p>脚落在骨盆底下那一下，膝盖是弯的，冲击由肌肉吸收；脚伸出去老远再落地，膝盖几乎是直的，冲击直接传给关节。这个区别在慢动作里看得一清二楚。</p><p>自查：让家人拿手机从侧面拍你跑十秒，慢放，看落地点在骨盆前面还是骨盆底下。在前面一大截的，就是步幅太大，先收小。</p><p><strong>量怎么加。</strong></p><p>“每周加量不超过 10%”这句话你肯定听过。它没有研究证明 10% 是那个神奇数字，属于经验法则〔C〕。但“突然翻倍”确实是新手受伤最常见的原因，膝盖、胫骨、跟腱都挨这一刀。</p><p>我的做法更保守：连续两周跑完都舒服，第三周才加。加完那周有点酸是正常的，疼到走路不舒服，就退回去。</p><p>大体重的人，先走跑交替：跑一分钟，走两分钟，重复八次。把总时长当目标，配速先别看。等这套能连着做四十分钟不难受，再谈纯跑。指南给的方向本来也是中低强度有氧为主、循序渐进〔G1，A〕。</p><p><img src="'+k+'" alt="跑步姿势：上坡用小步快频，下坡屈膝减速，落脚别伸到身体前面"></p><h2 id="_4-8-二区心率-一个被说烂了的概念" tabindex="-1">4.8　二区心率，一个被说烂了的概念 <a class="header-anchor" href="#_4-8-二区心率-一个被说烂了的概念" aria-label="Permalink to &quot;4.8　二区心率，一个被说烂了的概念&quot;">​</a></h2><p>先说一个容易踩的坑：“二区”在两套体系里不是一个东西。</p><p>做耐力研究的人常用三区模型：一区在第一个乳酸阈以下，二区在两个乳酸阈之间，三区在第二个阈值以上。他们关心的是强度怎么分布——精英耐力选手大部分时间待在一区，少量时间扎在三区，中间那一块反而不多，所以叫“极化训练”〔R17，B〕。</p><p>手表和教练说的五区是另一套，按最大心率的百分比切，二区大约 60% 到 70%。中文跑圈说“跑二区”“二区有氧”，多数指的是这一套，也就是“轻松、能说话”那一档。</p><p>所以有人跟你说“要多跑二区”，你可以先问一句：你说的是三区模型的二区，还是五区的二区。问清楚，能省掉一个月的糊涂。</p><p>这本书里说的二区，按五区那个意思：轻松有氧，能说话。</p><p><strong>这条线怎么定。</strong></p><p>最好用的是官方口径。《肥胖症诊疗指南（2024年版）》把中等强度定在最大心率的 50% 到 70%〔G1，A〕，跟五区的二区基本重合，直接拿来用就行。</p><p>最大心率得估。最常见的是 220 减年龄，这个公式误差不小；研究给的替代方案是 208 减 0.7 乘年龄，在更大的样本里拟合得更好〔R18，B〕。但它仍然是估的，个体差十下很正常。</p><p>真想要精确，只有一条路：跑一次递增负荷测试，把实际最大心率测出来。那要设备和场地，多数人不需要。</p><p>再给一个更专业的坐标：第一乳酸阈大约在血乳酸 2 毫摩尔每升的位置，第二乳酸阈大约 4 毫摩尔每升〔R19，B〕。三区模型那两条线就是它们。测过乳酸的人用这套数；没测过，看下一条。</p><p><strong>最实用的办法：说话测试。</strong></p><p>能整句说完、不喘断，就是中等强度；只能说短句、得换气，就偏上了；说不出话，那是高强度〔R20，B〕。这个方法在心脏康复里用了几十年，不要设备，误差比公式小。</p><p>所以你要是戴着手表却懒得算：跑起来，试着说一整句话，或者背一句诗。能顺顺当当说完，就在二区；说到一半要喘，过线了。</p><p><strong>算一遍。</strong></p><p>四十岁，最大心率按 208 减 0.7×40＝180。指南那条中等强度线是 50% 到 70%，也就是 90 到 126。</p><p>用 220 减年龄算，四十岁也是 180，巧了；五十岁就不一样了，220 版给 170，208 版给 173。差三下不算多，可你的整个区间跟着挪。</p><p>手表读数跟你算出来的对不上，多半是三件事：最大心率用的是默认值、手环心率在跑动时滞后、表带没戴紧。</p><p><strong>八成和两成。</strong></p><p>平时做有氧，八成放在能说话那一档，两成留给喘的时候——比如一周跑四次，三次轻松，一次稍快。这不是法律，是让你别把每次跑都跑成考试。</p><h2 id="_4-9-呼吸-能说的和不能说的" tabindex="-1">4.9　呼吸：能说的和不能说的 <a class="header-anchor" href="#_4-9-呼吸-能说的和不能说的" aria-label="Permalink to &quot;4.9　呼吸：能说的和不能说的&quot;">​</a></h2><p>网上有很多“三吸两呼”“两吸一呼”的口诀，说得像有讲究。我去找了研究，能找到的是动物身上呼吸节律和步频的耦合，拿来推人的跑步呼吸，不够；人体上专门比较固定呼吸节律和自然呼吸的研究，我没找到像样的〔C〕。</p><p>所以这一节我只说三件事。</p><p>第一，别数呼吸。呼吸跟着强度走，是身体自己调的。你刻意数，注意力反而从姿势和路面上挪开了。</p><p>第二，鼻子吸、嘴呼，或者全程用嘴，都行。天冷、空气干的时候用鼻子吸舒服一点，这是体感，不是研究结论〔C〕。</p><p>第三，把呼吸当仪表，别当任务。跑起来能不能说完一整句话——这就是你的强度表，比任何口诀都准〔R20，B〕。喘到说不出话，降下来；一路轻松，可以再加一点。</p><p>至于跑步时侧腹疼，常见说法是“呼吸节奏错了”。这个说法我没找到过硬证据；能确认的诱因主要是刚吃完就跑，以及膈肌和内脏韧带的牵拉〔C〕。实操就一句：饭后至少等一个半小时再跑。</p><h2 id="_4-10-再补几个动作" tabindex="-1">4.10　再补几个动作 <a class="header-anchor" href="#_4-10-再补几个动作" aria-label="Permalink to &quot;4.10　再补几个动作&quot;">​</a></h2><p>4.4 那三套是骨架，够你把大肌群练起来。这一节补八个更细的，都能在家做，不用器械。</p><p><strong>死虫</strong>——练核心稳定，重点是腰不塌。仰卧，双手朝上，双腿抬起屈髋屈膝各九十度，对侧的手和腿慢慢伸直再收回，腰始终贴地。</p><p><img src="'+B+'" alt="死虫分解图：左图手脚抬起、腰贴地，右图对侧手脚伸直但不塌腰"></p><p><strong>侧平板</strong>——侧腰和髋外侧。肘撑地，身体成一条线，髋别往下掉。撑不住就把下面的膝盖跪地。</p><p><img src="'+A+'" alt="侧平板分解图：左图肘撑地侧卧屈膝，右图撑起成一条线"></p><p><strong>俯卧背伸</strong>——背部和腰。趴着，手腿同时抬离地面一点点，停两秒，慢慢放下。别抬到腰疼，这不是比谁抬得高。</p><p><img src="'+C+'" alt="俯卧背伸分解图：左图趴平，右图手腿微微抬离地面"></p><p><strong>登台阶</strong>——大体重的人用它代替弓步，膝盖压力小。踩上台阶，后脚跟发力站直，再慢慢下来。台阶高度到膝盖下面一点就够。</p><p><img src="'+I+'" alt="登台阶分解图：左图一脚踩上台，右图站直并提膝"></p><p><strong>单腿臀桥</strong>——臀桥的进阶。一条腿伸直抬起，另一条腿的脚跟踩地顶髋。腰别代偿，顶到肩、髋、膝一条线就停。</p><p><img src="'+T+'" alt="单腿臀桥分解图：左图一条腿抬起，右图用支撑腿顶髋"></p><p><strong>登山跑</strong>——有氧加核心，心率上得快。撑地，两腿交替往胸口提。BMI 高的时候先别做，手腕和腰吃不消。</p><p><img src="'+R+'" alt="登山跑分解图：左图撑地把一腿提到胸前，右图换腿"></p><p><strong>快走和坡度走</strong>——最被低估的一项。跑步机坡度调到 5% 到 10%，速度放慢一点，心率一样上去，膝盖的负担比跑小得多。走的时候别死抓扶手，那是把体重卸给机器了。</p><p><img src="'+G+'" alt="坡度走示意图：把坡度调到 5% 到 10%，速度放慢，别抓扶手"></p><p><strong>跑后拉伸</strong>——小腿和髋前侧。跑完趁身体热着做，每个动作三十秒，慢慢呼，别弹震。</p><p><img src="'+M+'" alt="跑后拉伸分解图：左图弓步下压拉后腿髋前侧，右图屈髋拉前腿后侧"></p><p><img src="'+N+'" alt="髋前侧拉伸分解图：左图单膝跪地，右图重心前移"></p><p>这些动作的照片都来自 Free Exercise DB，公有领域，可以随便用〔S2〕。我把每个动作的起止两帧拼成一张，标了要点；动作本身没改，也不是我本人示范。</p><h2 id="_4-11-运动性价比排行-从夯到拉" tabindex="-1">4.11　运动性价比排行：从夯到拉 <a class="header-anchor" href="#_4-11-运动性价比排行-从夯到拉" aria-label="Permalink to &quot;4.11　运动性价比排行：从夯到拉&quot;">​</a></h2><p>哪项运动最值，这事儿能吵一晚上，因为“值”这个字没定义。我先说清楚我按什么排。</p><p>四条：花多少钱、占多少时间、学不学得会、赔不赔身体。再补一条我自己的：明天还愿不愿意做。</p><p>消耗按运动能耗表里的 MET 值换算〔R21，A〕：70 公斤的人动一小时，大概烧 MET × 70 千卡。这是我拿计算器算出来的，不是在你身上测的，个体差异能到两三成，当真数看会失望。</p><p><img src="'+E+'" alt="运动性价比排行图：从上到下五档，夯是坡度快走、慢跑、自重力量、骑行通勤；顶级是爬楼梯、跳绳、弹力带；人上人是居家跳操、游泳、健身房器械；NPC 是团课和私教；拉完了是家用大件和通勤远的场馆"></p><p>然后是价格的口径：钱按“开始这项运动最少要掏多少”算，不按“最贵能花多少”算。时间按“从出门到洗完澡”算，不按“手环上那 40 分钟”算——隐形的部分才是真正吃掉你的部分。</p><table tabindex="0"><thead><tr><th>项目</th><th>起步要花的钱</th><th>实际占的时间</th><th>门槛</th><th>70 公斤一小时</th><th>隐性成本</th><th>档位</th></tr></thead><tbody><tr><td>坡度快走</td><td>0</td><td>40–60 分钟</td><td>不用学</td><td>370–560 千卡</td><td>耗时长，得凑够时间</td><td>夯</td></tr><tr><td>慢跑</td><td>一双鞋</td><td>40–60 分钟</td><td>低，但关节要适应</td><td>490–690 千卡</td><td>跑量加太快会伤</td><td>夯</td></tr><tr><td>自重力量</td><td>0</td><td>20–30 分钟</td><td>要学动作</td><td>250–490 千卡</td><td>热量不高，收益在保肌肉</td><td>夯</td></tr><tr><td>骑行通勤</td><td>0（共享单车）到 3000</td><td>0，本来就通勤</td><td>会骑车</td><td>480–560 千卡</td><td>安全问题</td><td>夯</td></tr><tr><td>爬楼梯</td><td>0</td><td>10–20 分钟</td><td>不用学</td><td>约 620 千卡</td><td>下楼冲膝盖</td><td>顶级</td></tr><tr><td>跳绳</td><td>20 元一根绳</td><td>15–25 分钟</td><td>中等，要协调</td><td>770–860 千卡</td><td>冲击大，体重大先别跳</td><td>顶级</td></tr><tr><td>弹力带</td><td>50–100 元</td><td>20–30 分钟</td><td>要学几个动作</td><td>250–420 千卡</td><td>阻力有限，练到后面不够用</td><td>顶级</td></tr><tr><td>居家跳操、HIIT</td><td>0</td><td>20–30 分钟</td><td>低</td><td>460–560 千卡</td><td>动作不标准伤膝腰</td><td>人上人</td></tr><tr><td>游泳</td><td>30–60 元一次</td><td>90 分钟起</td><td>要会游</td><td>400–690 千卡</td><td>场地加通勤加洗澡</td><td>人上人</td></tr><tr><td>健身房器械</td><td>1500–3000 一年</td><td>90 分钟起</td><td>低</td><td>250–420 千卡</td><td>来回通勤是隐性税</td><td>人上人</td></tr><tr><td>团课、私教</td><td>200–500 一次</td><td>90 分钟起</td><td>低</td><td>350–560 千卡</td><td>钱花在“有人盯”上</td><td>NPC</td></tr><tr><td>家用大件器械</td><td>3000–10000</td><td>看你在不在家</td><td>低</td><td>跟户外一样</td><td>占地，最大风险是吃灰</td><td>拉完了</td></tr><tr><td>远距离场馆项目</td><td>场地费</td><td>单程半小时起</td><td>中</td><td>看项目</td><td>45 分钟的运动变成两小时行程</td><td>拉完了</td></tr></tbody></table><h3 id="夯-好到没什么可挑的" tabindex="-1">夯：好到没什么可挑的 <a class="header-anchor" href="#夯-好到没什么可挑的" aria-label="Permalink to &quot;夯：好到没什么可挑的&quot;">​</a></h3><p><strong>坡度快走</strong>是我心里的第一。跑步机坡度调到 5% 到 10%，速度降下来，心率一样上去，膝盖负担比跑小得多。一分钱不花，不用学，能打电话、能听书，下雨也能在室内做。它唯一的缺点是慢，四十分钟起步才有意义。</p><p><strong>慢跑</strong>的单位时间回报比快走高，70 公斤跑一小时五百到七百千卡，跑完还有一段“后燃”。代价写在明面上：前四周是关节适应期，跑量一周加超过一成，膝盖和小腿就开始找你算账。它夯，但不是新手第一天就该冲的项目。</p><p><strong>自重力量</strong>热量不高，按一千卡算账它排不进前三。但它决定你减下来是“瘦”还是“瘦得塌”。减重期掉的体重里有一部分是肌肉，指南明确说要靠抗阻训练把这部分守住〔G1，A〕。零成本、家里两平米就够，这一项不算性价比，算地基。</p><p><strong>骑行通勤</strong>是这张表里唯一时间成本为零的——你本来就要从家到公司，只是把屁股从座椅挪到车座上。共享单车零投入，自己的车一两千。它不额外占你一分钟，所以性价比算出来高得不讲道理。</p><h3 id="顶级-多花一点-但账还算得过来" tabindex="-1">顶级：多花一点，但账还算得过来 <a class="header-anchor" href="#顶级-多花一点-但账还算得过来" aria-label="Permalink to &quot;顶级：多花一点，但账还算得过来&quot;">​</a></h3><p><strong>爬楼梯</strong>：上楼梯的能耗是快走的两倍上下〔R21，A〕，十分钟抵二十分钟，一分钱不花。唯一要记的是上楼练、下楼坐电梯——下楼那一下对膝盖的冲击是上楼的几倍，白送的亏不吃。</p><p><strong>跳绳</strong>效率最高，一千卡/小时那条线上它排前面，一根绳二十块。但它同时要协调、要场地、要能承受落地冲击，体重大的人前四到六周别碰，先走路。</p><p><strong>弹力带</strong>是家里最划算的一件器材。五六十块一根，抽屉里就能收，臀桥、划船、侧平举、深蹲都能加阻力。它排不到夯，是因为阻力有上限，练到半年以后你会觉得不够用；在那之前，它能把自重训练的天花板往下推很久。</p><h3 id="人上人-花钱办事-用上了才算值" tabindex="-1">人上人：花钱办事，用上了才算值 <a class="header-anchor" href="#人上人-花钱办事-用上了才算值" aria-label="Permalink to &quot;人上人：花钱办事，用上了才算值&quot;">​</a></h3><p><strong>居家跳操和 HIIT</strong> 的好处是快，二十分钟结束战斗；坏处是“累”和“有效”不是一回事。跟着视频乱蹦，动作一散，膝和腰先出问题。</p><p><strong>游泳</strong>对关节最友好，体重再大也不压膝盖，一小时 400 到 690 千卡。但它的真实成本不是票价，是场地、通勤、洗澡加起来一个半小时起——同样的时间，快走能走两趟。</p><p><strong>健身房器械</strong>买到的其实不是器械，是齐全、氛围和可加重量。年卡一两千不贵，贵的是每天来回那四十分钟。住得远的人，这笔税比年卡贵。</p><h3 id="npc-不坏-但也没多好" tabindex="-1">NPC：不坏，但也没多好 <a class="header-anchor" href="#npc-不坏-但也没多好" aria-label="Permalink to &quot;NPC：不坏，但也没多好&quot;">​</a></h3><p><strong>团课</strong>。一群人一起练，有音乐有人喊，气氛确实能推你多动十分钟。但你交的钱里有一大半买的是气氛，动作对不对，教练一个人看不过来七八个人。</p><p><strong>私教</strong>不是没用。对一个完全不知道怎么开始的人，“有人盯着、有人纠动作”值这个钱，前面几节课能把深蹲、硬拉这些基本动作教会你。但对已经能自己练的人，你花的是溢价——买的是准时到场，不是方法。同一个动作练三个月之后，你需要的是加重量，不是再交十节课的钱。</p><h3 id="拉完了-钱和时间都花在过程上" tabindex="-1">拉完了：钱和时间都花在过程上 <a class="header-anchor" href="#拉完了-钱和时间都花在过程上" aria-label="Permalink to &quot;拉完了：钱和时间都花在过程上&quot;">​</a></h3><p><strong>家用大件</strong>：跑步机、椭圆机，机器本身和健身房那台没区别，跑起来消耗也一样。它的成本结构是“钱一次性花完、地方一直占着、用不用全看你”。我没查过家用器械的闲置率，不编数；你只要想想身边买过跑步机的朋友，心里就有数了。</p><p><strong>通勤远的场馆项目</strong>最冤：运动四十五分钟，路上来回一小时，洗澡二十分钟。你不是没时间运动，是把时间花在了路上。</p><p><strong>还有一个坑</strong>：先买装备再开始。鞋、表、衣服、补剂，一口气买齐，人反而被这些准备工作拖住了。真要买，等这件事你已经做了四周再买。</p><h3 id="一句话的排序原则" tabindex="-1">一句话的排序原则 <a class="header-anchor" href="#一句话的排序原则" aria-label="Permalink to &quot;一句话的排序原则&quot;">​</a></h3><p>今天下楼就能做、明天还愿意做的，夯。</p><p>得开车、得预约、得先买个大件、得等一个天气才能开始的，拉完了。</p><p>中间那三档，网络上的叫法是顶级、人上人、NPC；说的其实就是“多花点钱、多欠点条件，值不值”这一件事。</p><p>最贵的从来不是私教和年卡，是买完不用。</p><p>这张表是我按上面那四个口径自己排的，不是学术结论。你要把“社交”算进性价比，团课和球场的名次会往前挪好几位；你要是只有晚上十点以后有时间，健身房反而成了唯一选项。口径变了，排名就会变，这话我认。</p><hr><p>下一部分给一个能直接照着做的东西：30 天。</p>',213)])])}const O=p(S,[["render",D]]);export{J as __pageData,O as default};
